INSERT INTO reviews (client_name, service_label, stars, body, is_public) VALUES ('Marlyse N.', 'Knotless Box Braids', 5, 'Blessing did my knotless braids in under four hours and my scalp never hurt once. Six weeks later they still looked fresh. This is the only place I trust now.', 1);
INSERT INTO reviews (client_name, service_label, stars, body, is_public) VALUES ('Josiane B.', 'Gel Overlay & Nail Art', 5, 'Grace is an artist. I showed her a blurry screenshot and she recreated it better than the picture. The salon itself feels like a little palace.', 1);
INSERT INTO reviews (client_name, service_label, stars, body, is_public) VALUES ('Ndeye F.', 'Deep Cleanse Facial', 5, 'My skin has completely changed since I started monthly facials with Linda. She explains every step and never rushes you.', 1);
INSERT INTO reviews (client_name, service_label, stars, body, is_public) VALUES ('Sylvie O.', 'Hot Stone Therapy', 5, 'I booked on my phone in two minutes on a Sunday night. Walked in Monday after work and left feeling brand new. Highly recommend.', 1);
INSERT INTO reviews (client_name, service_label, stars, body, is_public) VALUES ('Chantal M.', 'Silk Press', 5, 'Aïcha gives the sleekest silk press in Yaoundé — no heat damage, and it lasts me three full weeks even in the rain.', 1);
INSERT INTO reviews (client_name, service_label, stars, body, is_public) VALUES ('Rachel A.', 'Wig Install', 5, 'The melt was invisible. My colleagues genuinely thought it was my own hairline. Booking again for December already.', 1);
INSERT INTO faqs (category, question, answer, is_public, sort_order) VALUES ('Booking', 'Do I need an appointment or can I walk in?', 'Booked clients always come first, and Saturdays are almost always full. We do take walk-ins when there is a genuine gap, but we cannot promise one — booking online takes about two minutes and guarantees the chair.', 1, 0);
INSERT INTO faqs (category, question, answer, is_public, sort_order) VALUES ('Booking', 'How far ahead can I book?', 'Three weeks. If you need something further out — a wedding, a trip — message us on WhatsApp and we will put it in the diary manually.', 1, 1);
INSERT INTO faqs (category, question, answer, is_public, sort_order) VALUES ('Booking', 'Can I book more than one service at once?', 'Yes. Select everything you want in the first step of the booking flow and we will block out enough time for all of it. Where two services can run at the same time, such as braids and nails, we assign two stylists.', 1, 2);
INSERT INTO faqs (category, question, answer, is_public, sort_order) VALUES ('Booking', 'How do I change or cancel?', 'Use Manage Booking with your reference code, or call the salon. Cancellation is free up to four hours before your slot.', 1, 3);
INSERT INTO faqs (category, question, answer, is_public, sort_order) VALUES ('Payment', 'What payment methods do you accept?', 'Cash, MTN Mobile Money, Orange Money and card. You settle at the chair after your service — nothing is charged when you book online.', 1, 4);
INSERT INTO faqs (category, question, answer, is_public, sort_order) VALUES ('Payment', 'Do I have to pay a deposit?', 'Only for services over 20,000 FCFA, and mostly on Saturdays. It is 30% by MoMo and it comes off your final bill.', 1, 5);
INSERT INTO faqs (category, question, answer, is_public, sort_order) VALUES ('Payment', 'Are your prices final?', 'The price on the site is what you pay. If a style needs extra product or extra time, we quote you before we start — never after.', 1, 6);
INSERT INTO faqs (category, question, answer, is_public, sort_order) VALUES ('Services', 'Do I bring my own hair for braids?', 'Braid prices cover labour, so you can bring your own. We also sell Kanekalon and pre-stretched hair at the counter if it is easier.', 1, 7);
INSERT INTO faqs (category, question, answer, is_public, sort_order) VALUES ('Services', 'How long do knotless braids take?', 'Around four hours for a full head at medium length. Longer or smaller braids take more — the booking flow shows the exact time when you pick the service.', 1, 8);
INSERT INTO faqs (category, question, answer, is_public, sort_order) VALUES ('Services', 'Will a relaxer or silk press damage my hair?', 'Not the way we do it. We use heat protection on every press and we will tell you honestly if a look is going to damage your hair rather than just taking the money.', 1, 9);
INSERT INTO faqs (category, question, answer, is_public, sort_order) VALUES ('Visit', 'What if I am running late?', 'Message us on WhatsApp. We hold your chair for 15 minutes; after that the slot may go to someone else and the booking is marked a no-show.', 1, 10);
INSERT INTO faqs (category, question, answer, is_public, sort_order) VALUES ('Visit', 'Can I bring my children?', 'Of course — and we braid for them too. Kids braiding is a service in its own right, so book them a slot rather than adding them on the day.', 1, 11);
INSERT INTO faqs (category, question, answer, is_public, sort_order) VALUES ('Visit', 'Is there parking?', 'Yes, along the main road right outside. We are on the first floor — look for the gold crown sign above the entrance.', 1, 12);
